using namespace std;

/* State of the buffered result writer.
 *
 * Result tuples are accumulated in a single block of the buffer. As soon as
 * the next tuple would no longer fit (the last PTR_SIZE bytes of every block
 * are reserved for the address of the following block) the block is flushed
 * to disk and a fresh one is taken from the buffer.
 *
 * pushToWrite(buf, NULL, 0, addr, true)        -> start a new result at addr
 * pushToWrite(buf, tuple, sizeof(tuple), addr) -> append one tuple
 * pushToWrite(buf, NULL, 0, addr, false, true) -> flush the last block
 */
static unsigned char *writeBlk = NULL; /* block currently being filled */
static size_t writeOff = 0;            /* bytes already used in writeBlk */
static unsigned int writeAddr = 0;     /* disk address of writeBlk */

void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
{
^Iif (reset)
^I{
^I^I/* The buffer the previous result was written with may already be
^I^I * gone, so never touch writeBlk here - just forget about it. */
^I^IwriteBlk = NULL;
^I^IwriteOff = 0;
^I^IwriteAddr = addr;
^I^Ireturn;
^I}

^Iif (buf == NULL)
^I^Ireturn;

^Iconst size_t capacity = buf->blkSize - PTR_SIZE; /* usable payload bytes */

^Iif (source != NULL && size > 0)
^I{
^I^Iif (writeBlk == NULL)
^I^I{
^I^I^Iif ((writeBlk = getNewBlockInBuffer(buf)) == NULL)
^I^I^I^Ireturn;
^I^I^Imemset(writeBlk, 0, buf->blkSize);
^I^I^IwriteOff = 0;
^I^I}

^I^Iif (writeOff + size > capacity)
^I^I{
^I^I^I/* Full: chain this block to the next one and flush it. */
^I^I^Iunsigned int next = writeAddr + 1;
^I^I^Imemcpy(writeBlk + buf->blkSize - PTR_SIZE, &next, PTR_SIZE);
^I^I^IwriteBlockToDisk(writeBlk, writeAddr, buf);
^I^I^IwriteAddr = next;

^I^I^Iif ((writeBlk = getNewBlockInBuffer(buf)) == NULL)
^I^I^I{
^I^I^I^IwriteOff = 0;
^I^I^I^Ireturn;
^I^I^I}
^I^I^Imemset(writeBlk, 0, buf->blkSize);
^I^I^IwriteOff = 0;
^I^I}

^I^Imemcpy(writeBlk + writeOff, source, size);
^I^IwriteOff += size;
^I}

^Iif (push && writeBlk != NULL)
^I{
^I^I/* Last block of the result: the next-block address stays 0. */
^I^Iunsigned int next = 0;
^I^Imemcpy(writeBlk + buf->blkSize - PTR_SIZE, &next, PTR_SIZE);
^I^IwriteBlockToDisk(writeBlk, writeAddr, buf);
^I^IwriteAddr++;
^I^IwriteBlk = NULL;
^I^IwriteOff = 0;
^I}
}

void readTuplesFromBlock(unsigned char *blk, Relation *R)
{
^Iif (blk == NULL || R == NULL)
^I^Ireturn;

^I/* A relation block stores TUPLE_PER_BLK tuples of two 4-byte integers,
^I * followed by the address of the next block of the relation. */
^Ifor (int i = 0; i < TUPLE_PER_BLK; i++)
^I{
^I^Imemcpy(&R[i].attr1, blk + i * 2 * PTR_SIZE, PTR_SIZE);
^I^Imemcpy(&R[i].attr2, blk + i * 2 * PTR_SIZE + PTR_SIZE, PTR_SIZE);
^I}
