#include <stdlib.h>
#include <stdio.h>
#include <string.h> // added for memset
#include "extmem.h"

Buffer *initBuffer(size_t bufSize, size_t blkSize, Buffer *buf)
{
^Iif (buf == NULL || blkSize == 0)
^I^Ireturn NULL;

^I/* Every block occupies blkSize + 1 bytes of the buffer: one leading byte
^I * flags whether the slot is available, the remaining blkSize bytes hold
^I * the block payload that is handed out to the caller. */
^Ibuf->numIO = 0;
^Ibuf->bufSize = bufSize;
^Ibuf->blkSize = blkSize;
^Ibuf->numAllBlk = bufSize / (blkSize + 1);
^Ibuf->numFreeBlk = buf->numAllBlk;

^Iif ((buf->data = (unsigned char *)malloc(bufSize)) == NULL)
^I{
^I^Iperror("Buffer Initialization Failed!\n");
^I^Ireturn NULL;
^I}

^Imemset(buf->data, 0, bufSize); /* every slot starts out BLOCK_AVAILABLE */

^Ireturn buf;
}

void freeBuffer(Buffer *buf)
{
^Ifree(buf->data);
}

unsigned char *getNewBlockInBuffer(Buffer *buf)
{
^Iunsigned char *blkPtr;
^Isize_t i;

^Iif (buf == NULL || buf->numFreeBlk == 0)
^I{
^I^Iperror("Buffer Overflows!\n");
^I^Ireturn NULL;
^I}

^I/* Scan the slots for the first available one, mark it used and return
^I * the payload address (the byte right after the availability flag). */
^Ifor (i = 0; i < buf->numAllBlk; i++)
^I{
^I^IblkPtr = buf->data + i * (buf->blkSize + 1);
^I^Iif (*blkPtr == BLOCK_AVAILABLE)
^I^I{
^I^I^I*blkPtr = BLOCK_UNAVAILABLE;
^I^I^Ibuf->numFreeBlk--;
^I^I^Ireturn blkPtr + 1;
^I^I}
^I}

^Iperror("Buffer Overflows!\n");
^Ireturn NULL;
}

void freeBlockInBuffer(unsigned char *blk, Buffer *buf)
{
^Iif (blk == NULL || buf == NULL)
^I^Ireturn;

^I/* The availability flag sits one byte in front of the payload. */
^Iunsigned char *blkPtr = blk - 1;

^Iif (*blkPtr == BLOCK_AVAILABLE) /* already free: do not double count */
^I^Ireturn;

^I*blkPtr = BLOCK_AVAILABLE;
^Imemset(blk, 0, buf->blkSize);
^Ibuf->numFreeBlk++;
}

int dropBlockOnDisk(unsigned int addr)
{
^Ichar filename[40];

^Isprintf(filename, "%d.blk", addr);

^Iif (remove(filename) == -1)
^I{
^I^Iperror("Dropping Block Fails!\n");
^I^Ireturn -1;
^I}

^Ireturn 0;
}

unsigned char *readBlockFromDisk(unsigned int addr, Buffer *buf)
{
^IFILE *fp;
^Ichar filename[40];
^Iunsigned char *blkPtr;

^Iif (buf == NULL)
^I^Ireturn NULL;

^Iif ((blkPtr = getNewBlockInBuffer(buf)) == NULL)
^I^Ireturn NULL;

^Isprintf(filename, "%d.blk", addr);

^Iif ((fp = fopen(filename, "rb")) == NULL)
^I{
^I^Iperror("Reading Block Fails!\n");
^I^IfreeBlockInBuffer(blkPtr, buf);
^I^Ireturn NULL;
^I}

^Ifread(blkPtr, buf->blkSize, 1, fp);
^Ifclose(fp);

^Ibuf->numIO++; /* one more I/O */

^Ireturn blkPtr;
}

int writeBlockToDisk(unsigned char *blkPtr, unsigned int addr, Buffer *buf)
{
^IFILE *fp;
^Ichar filename[40];

^Iif (blkPtr == NULL || buf == NULL)
^I^Ireturn -1;

^Isprintf(filename, "%d.blk", addr);

^Iif ((fp = fopen(filename, "wb+")) == NULL)
^I{
^I^Iperror("Writing Block Fails!\n");
^I^Ireturn -1;
^I}

^Iif (fwrite(blkPtr, buf->blkSize, 1, fp) == 0)
^I{
^I^Iperror("Writing Block Fails!\n");
^I^Ifclose(fp);
^I^Ireturn -1;
^I}

^Ifclose(fp);

^I/* The block has been flushed, hand its slot back to the buffer. */
^IfreeBlockInBuffer(blkPtr, buf);

^Ibuf->numIO++; /* one more I/O */

^Ireturn 0;
}
